def P(text, style='BodyX'): return Paragraph(text, styles[style])
def title(text): return P(text, 'H1X')
def h2(text): return P(text, 'H2X')
def bullets(items):
    return [Paragraph('&bull; ' + x, styles['BodyX']) for x in items]

def table(data, widths=None, fs=8.5):
    rows=[]
    for ridx,row in enumerate(data):
        rows.append([Paragraph(str(cell), ParagraphStyle('t', parent=styles['Small'], fontName='Helvetica-Bold' if ridx==0 else 'Helvetica', fontSize=fs, leading=fs+3, textColor=colors.white if ridx==0 else SLATE)) for cell in row])
    t=Table(rows, colWidths=widths, repeatRows=1, hAlign='LEFT')
    t.setStyle(TableStyle([
        ('BACKGROUND',(0,0),(-1,0),NAVY),('TEXTCOLOR',(0,0),(-1,0),colors.white),
        ('GRID',(0,0),(-1,-1),0.35,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),
        ('BACKGROUND',(0,1),(-1,-1),colors.white),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white, PALE]),
        ('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)
    ]))
    return t

class ScreenshotBox(Flowable):
    def __init__(self, label, detail, height=260):
        Flowable.__init__(self); self.label=label; self.detail=detail; self.height=height; self.width=460
    def wrap(self, aw, ah): self.width=aw; return aw,self.height
    def draw(self):
        c=self.canv; c.saveState(); c.setStrokeColor(BLUE); c.setLineWidth(1.2); c.setDash(6,4)
        c.setFillColor(HexColor('#F8FAFC')); c.roundRect(0,0,self.width,self.height,8,stroke=1,fill=1)
        c.setDash(); c.setFillColor(BLUE); c.setFont('Helvetica-Bold',11); c.drawCentredString(self.width/2,self.height/2+12,'[SCREENSHOT REQUIRED: '+self.label+']')
        c.setFillColor(SLATE); c.setFont('Helvetica',9); words=self.detail.split(); lines=[]; line=''
        for word in words:
            if stringWidth(line+' '+word,'Helvetica',9) > self.width-50: lines.append(line); line=word
            else: line=(line+' '+word).strip()
        lines.append(line); y=self.height/2-10
        for line in lines: c.drawCentredString(self.width/2,y,line); y-=13
        c.restoreState()

class Architecture(Flowable):
    def __init__(self): Flowable.__init__(self); self.width=460; self.height=260
    def wrap(self,aw,ah): self.width=aw; return aw,self.height
    def draw(self):
        c=self.canv; c.saveState(); w=self.width
        boxes=[(10,180,110,45,'User Browser\nReact SPA'),(165,180,125,45,'Node.js / Express\nREST API'),(335,180,115,45,'SQL Server\nStored Procedures'),(65,70,130,45,'RabbitMQ\nCelery Message'),(265,70,150,45,'Python KYC Worker\nOpenCV + Tesseract')]
        for x,y,bw,bh,label in boxes:
            c.setFillColor(PALE); c.setStrokeColor(BLUE); c.roundRect(x,y,bw,bh,6,fill=1,stroke=1)
            c.setFillColor(NAVY); c.setFont('Helvetica-Bold',9); yy=y+bh/2+5
            for line in label.split('\n'): c.drawCentredString(x+bw/2,yy,line); yy-=12
        def arrow(x1,y1,x2,y2):
            c.setStrokeColor(SLATE); c.setFillColor(SLATE); c.setLineWidth(1); c.line(x1,y1,x2,y2); import math
            a=math.atan2(y2-y1,x2-x1); s=6; c.line(x2,y2,x2-s*math.cos(a-.45),y2-s*math.sin(a-.45)); c.line(x2,y2,x2-s*math.cos(a+.45),y2-s*math.sin(a+.45))
        arrow(120,202,165,202); arrow(290,202,335,202); arrow(220,180,130,115); arrow(195,92,265,92); arrow(340,115,390,180)
        c.setFillColor(GREY); c.setFont('Helvetica',8); c.drawCentredString(w/2,18,'Synchronous requests use the REST API; KYC tasks are published to the Celery queue and results update SQL Server and the webhook.')
        c.restoreState()

def footer(c, doc):
    if doc.page > 2:
        c.saveState(); c.setStrokeColor(LINE); c.line(2*cm,1.55*cm,A4[0]-2*cm,1.55*cm)
        c.setFont('Helvetica',8); c.setFillColor(GREY); c.drawString(2*cm,1.1*cm,'EDUVORA Project Report')
        c.drawRightString(A4[0]-2*cm,1.1*cm,f'Page {doc.page}')
        c.restoreState()

