story += [title('10. CHALLENGES AND LIMITATIONS'), h2('10.1 Integration Boundaries'), P('The system spans JavaScript and Python runtimes plus SQL Server, RabbitMQ, Cashfree, Google OAuth, SMTP and file repositories. The KYC workflow therefore depends on shared configuration and compatible path access between the Node API and Python worker. The Node publisher constructs a Celery protocol message through RabbitMQ\'s management HTTP API rather than an AMQP library, which is a deliberate cross-runtime integration detail requiring the RabbitMQ management endpoint.'), h2('10.2 Implementation Limitations'), *bullets(['Course playback and curriculum are currently mock data in CoursePlayer; no inspected API supplies enrolment/course content.', 'Orders and earnings screens contain static/local display data; no matching backend order-history, wallet, commission or withdrawal endpoints are exposed.', 'KYC accepts PDF MIME type but the Python quality checker uses cv2.imread, which cannot load a PDF as an image; a PDF may consequently fail worker quality processing.', 'The worker callback URL is fixed to a localhost address in tasks.py, limiting deployment portability unless configuration is changed.', 'KYC status logic has a potentially confusing interim state: submission procedure documentation says it sets IsKYCVerified while worker processing can still later reject the request.', 'No automated tests, CI pipeline, deployment configuration or database migration scripts were found.']), PageBreak()]

story += [title('11. CONCLUSION'), P('EDUVORA demonstrates a substantial web-development architecture centred on authenticated account workflows, SQL Server stored-procedure integration, referral relationships, package-payment initiation and an asynchronous identity-document pipeline. Its strongest technically verified contribution is the KYC flow: it separates immediate web-request handling from heavier document validation through RabbitMQ and Celery, adds image-quality checks and Aadhaar masking, and uses controlled temporary/permanent storage transitions.'), P('The project also provides a broad and polished React interface for profile, referral, network, package, course, order and earnings experiences. A submission should distinguish this interface scope from the live backend scope: profile, referral, network, packages, payment initiation and KYC have visible route/controller implementations, while course curriculum, order history and earnings values remain presentation-stage data in the inspected codebase.'), h2('11.1 Future Enhancements'), *bullets(['Add secured live APIs and SQL procedures for purchased courses, course progress, orders, commissions, wallet transactions and withdrawals.', 'Replace mock course/order/earnings data with protected server queries and apply user-level authorization.', 'Verify Cashfree webhook signatures and authenticate the internal KYC callback.', 'Make worker callback URL, OCR binary path and storage locations environment-configurable for deployment.', 'Handle PDF KYC documents with an explicit rasterisation/extraction path or restrict worker-bound image uploads to supported formats.', 'Add unit, integration and end-to-end tests, database migrations, CI and deployment documentation.', 'Audit the super-admin route and enforce verified role checks on both client navigation and server APIs.']), PageBreak()]

story += [title('12. BIBLIOGRAPHY'), table([['Source','Use in this report'],['EDUVORA backend/brain.md','Database schema and stored-procedure documentation.'],['EDUVORA backend source','Routes, controllers, middleware, utilities, payment/KYC integrations and environment-variable categories.'],['EDUVORA frontend source','Routes, Redux state, screens, components, static-data boundaries and build configuration.'],['EDUVORA kyc-python-worker source','Celery task, RabbitMQ configuration, image quality, Aadhaar masking and SQL repository logic.'],['Package manifests and lockfiles','Verified frameworks and library dependencies.'],['Reference PDF: AI Career Prep Platform Report','Section order, academic tone, A4 report structure, certificate/abstract/acknowledgement/TOC pattern and screenshot convention.']], [6.5*cm,9.5*cm]), Spacer(1,1*cm), P('Prepared for submission by Indrasish Biswas, Roll / Registration No. 24E102B91, B.Tech CSE.', 'Cap')]

